    94	export async function fetchDirectFromAPIs() {
    95	  console.warn('[EventService] WARNING: Using deprecated direct API endpoint');
    96	  
    97	  const data = await fetchFromAPI('/debug-direct-events');
    98	  
    99	  if (data.error || !data.ticketmaster) {
   100	    return {
   101	      events: [],
   102	      sources: [],
   103	      metadata: {
   104	        data_source: 'direct_api',
   105	        debug_only: true,
   106	        warning: 'DEPRECATED: Raw data from provider APIs, not normalized'
   107	      }
   108	    };
   109	  }
   110	  
   111	  const allEvents = [];
   112	  
