   145	/**
   146	 * Fetch events with fallback (development mode only)
   147	 * WARNING: Only enabled when USE_DIRECT_API_FALLBACK=true
   148	 */
   149	export async function fetchEventsWithFallback() {
   150	  // Try Supabase first (always)
   151	  const supabaseData = await fetchFromSupabase();
   152	  
   153	  if (supabaseData.events.length > 0) {
   154	    return supabaseData;
   155	  }
   156	  
   157	  // Only use fallback if explicitly enabled
   158	  if (USE_DIRECT_API_FALLBACK) {
   159	    console.warn('[EventService] WARNING: Falling back to direct API (development only!)');
   160	    return fetchDirectFromAPIs();
   161	  }
   162	  
   163	  // No fallback - return empty with clear error
   164	  return {
   165	    events: [],
   166	    sources: [],
   167	    metadata: {
   168	      data_source: 'supabase',
   169	      fallback_used: false,
   170	      error: 'No events in Supabase. Fallback disabled.',
   171	      action_required: 'Run ingestion pipeline to populate Supabase'
   172	    }
   173	  };
   174	}
